    enable: false
}
function testAppendNonEmptyLists() {
    int[] list1 = [1, 2];
    int[] list2 = [2, 3, 4, 5];
    int[] result = append(list1, list2);
    int[] expected = [1, 2, 2, 3, 4, 5];
    test:assertEquals(result, expected);
